/**
 * QA: heavy-industrial-capacity-update-2026q3
 * // viz-types: diverging ?? bars, stacked ship-layer bars, steel share path+bars, order-backlog scatter, aircraft race bars, forge strip | layout: default
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import {
  FORGE_SHOPS,
  HEADLINE,
  ORDER_SHARE_ROWS,
  STEEL_H1_LEADERS,
  VINTAGE_DELTAS,
} from "../src/data/heavy-industrial-capacity-update-2026q3-data.ts";

assert.equal(HEADLINE.chinaOrderSharePct, 72.0);
assert.equal(HEADLINE.chinaOrderDeltaVsCompletionsPp, 19.8);
assert.equal(HEADLINE.chinaSteelH1SharePct, 53.7);
assert.equal(HEADLINE.chinaSteelShareDeltaPp, 1.7);
assert.equal(HEADLINE.ultraHeavyForgeShops, 6);
assert.ok(FORGE_SHOPS.length === 6);
assert.ok(ORDER_SHARE_ROWS.length >= 3);
assert.ok(STEEL_H1_LEADERS.length >= 5);
assert.ok(VINTAGE_DELTAS.some((d) => d.id === "china-orders" && d.deltaPp === 19.8));

const root = process.cwd();
const slug = "heavy-industrial-capacity-update-2026q3";
const markers = [
  "China Takes 72% of H1 Ship Orders",
  "Q3 2026 vintage ?? ?? vs Aug completions update",
];

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4188);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  try {
    const urlA = `http://127.0.0.1:${port}/blog/${slug}.html`;
    const urlB = `http://127.0.0.1:${port}/blog/${slug}/`;
    let loaded = false;
    for (const url of [urlA, urlB]) {
      try {
        await page.goto(url, { waitUntil: "networkidle", timeout: 45000 });
        loaded = true;
        break;
      } catch {
        /* try next */
      }
    }
    if (!loaded) throw new Error(`Failed to load blog page for ${slug}`);

    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    for (const label of [
      "Vintage ??",
      "Ship layers",
      "Steel H1",
      "Order vs backlog",
      "Aircraft YTD",
      "Forges held",
    ]) {
      const btn = page.getByRole("button", { name: label });
      if (await btn.count()) {
        await btn.first().click();
        await page.waitForTimeout(400);
      }
    }
    await page.getByRole("button", { name: "Vintage ??" }).first().click();
    for (const f of ["Moved only", "Held / flat", "All"]) {
      const btn = page.getByRole("button", { name: f });
      if (await btn.count()) {
        await btn.first().click();
        await page.waitForTimeout(250);
      }
    }
    await page.getByRole("button", { name: "Steel H1" }).first().click();
    for (const f of ["YoY %", "H1 Mt", "H1 share"]) {
      const btn = page.getByRole("button", { name: f });
      if (await btn.count()) {
        await btn.first().click();
        await page.waitForTimeout(250);
      }
    }
    console.log(`??? QA passed for ${slug}`);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

